import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"查看运维记录","description":"筛选操作记录和系统事件，读取执行明细，区分已受理、执行中、完成与陈旧观测。","frontmatter":{"title":"查看运维记录","description":"筛选操作记录和系统事件，读取执行明细，区分已受理、执行中、完成与陈旧观测。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/operations-records.md","filePath":"zh/使用指南/查看运维记录.md"}'),i={name:"zh/guide/operations-records.md"};function n(d,e,l,s,h,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="查看运维记录" tabindex="-1">查看运维记录 <a class="header-anchor" href="#查看运维记录" aria-label="Permalink to &quot;查看运维记录&quot;">​</a></h1><p>入口是 <strong>“运维管理” → “运维记录”</strong>。工程人员、运维人员和组织管理员按权限查看，不同账号看到的对象范围可能不同。</p><p>这里用于核对任务与事件，不是重新提交部署或重启的快捷入口。</p><h2 id="_1-找到对应记录" tabindex="-1">1. 找到对应记录 <a class="header-anchor" href="#_1-找到对应记录" aria-label="Permalink to &quot;1. 找到对应记录&quot;">​</a></h2><ol><li>先确定要查的工程、环境、节点或中心系统事件。</li><li>按对象或操作搜索，结合记录类型、对象类型、环境、状态和时间范围筛选。</li><li>查看列表中的对象、时间、操作或事件、状态及耗时。</li><li>打开对应记录，阅读 **“执行明细”**或“记录详情”。</li></ol><p>没有结果时先放宽时间和筛选，不认定操作没有发生。环境筛选只包含明确关联到该环境的记录；未关联环境的节点或中心系统事件，需在“全部环境”查看。</p><h2 id="_2-怎样理解状态" tabindex="-1">2. 怎样理解状态 <a class="header-anchor" href="#_2-怎样理解状态" aria-label="Permalink to &quot;2. 怎样理解状态&quot;">​</a></h2><p>“已受理”表示请求已进入处理，“执行中”表示仍在推进；是否完成、失败或恢复，要看后续记录和目标对象的实际状态。</p><p>一条“已恢复”事件不表示整个工程的页面、数据与全部引擎都已验收。记录里有成功，也要核对是不是本次目标、版本和时间。</p><p>读取详情失败时先重试，不把空白明细解释为任务没有步骤或没有报错。</p><h2 id="_3-留意更新中断和陈旧数据" tabindex="-1">3. 留意更新中断和陈旧数据 <a class="header-anchor" href="#_3-留意更新中断和陈旧数据" aria-label="Permalink to &quot;3. 留意更新中断和陈旧数据&quot;">​</a></h2><p>出现 **“更新暂未完成，当前保留上次记录。”**或加载中断提示时，列表仍可能展示旧数据。先重试并检查更新状态，不以旧记录确认当前已经正常。</p><p>操作结果不明确时，保留已有提示和对象信息，先检查最新记录与实际服务，不立即重复创建、停止或删除。</p><h2 id="_4-求助时提供什么" tabindex="-1">4. 求助时提供什么 <a class="header-anchor" href="#_4-求助时提供什么" aria-label="Permalink to &quot;4. 求助时提供什么&quot;">​</a></h2><p>提供对象名称、所属环境、操作、发生时间、当前状态和脱敏错误，有助于维护人员定位。</p><p>不要提交登录 Cookie、接入码、模型密钥、数据库密码、设备凭据或含敏感信息的完整日志。需要导出或分享记录时，先按组织要求处理敏感内容。</p><p>下一步：<a href="/induframe-docs/zh/guide/deployments.html">工程部署</a> · <a href="/induframe-docs/zh/guide/runtime-nodes.html">运行节点</a> · <a href="/induframe-docs/zh/guide/runtime-environments.html">运行环境</a>。</p>',17)])])}const u=a(i,[["render",n]]);export{c as __pageData,u as default};
